type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
type Flag = { rollout: number; countries: readonly string[] };

function defineFlow<const T extends readonly OrderStatus[]>(steps: T): T {
  return steps;
}

function oneOf<const T extends readonly string[]>(values: T) {
  return (input: string): input is T[number] => (values as readonly string[]).includes(input);
}

function defineFlags<const T extends Record<string, Flag>>(flags: T): T {
  return flags;
}

// ---- Type tests (do not edit) ----
const happyPath = defineFlow(['processing', 'shipped', 'delivered']);
type T1 = Expect<Equal<typeof happyPath, readonly ['processing', 'shipped', 'delivered']>>;

// @ts-expect-error: 'refunded' is not an order status
defineFlow(['processing', 'refunded']);

const isChannel = oneOf(['web', 'mobile_app', 'marketplace']);
const raw: string = 'mobile_app';
if (isChannel(raw)) {
  type T2 = Expect<Equal<typeof raw, 'web' | 'mobile_app' | 'marketplace'>>;
}

const flags = defineFlags({
  expressShipping: { rollout: 0.5, countries: ['EG', 'AE'] },
  giftWrap: { rollout: 1, countries: [] },
});
type T3 = Expect<Equal<typeof flags.expressShipping.countries, readonly ['EG', 'AE']>>;

// @ts-expect-error: every flag needs a rollout
defineFlags({ applePay: { countries: ['US'] } });

console.log(happyPath, isChannel('web'), isChannel('fax'), flags.expressShipping.countries);
